    </div>

    <el-card v-if="!assignments.length" class="empty-card"><el-empty description="Lớp này chưa có bài tập"><el-button type="primary" @click="openCreate">Tạo bài tập đầu tiên</el-button></el-empty></el-card>

    <el-tabs v-else v-model="activeId" class="assignment-tabs" @tab-change="loadMatrix">
      <el-tab-pane v-for="assignment in assignments" :key="assignment.id" :name="assignment.id" :label="assignment.title">
        <div class="assignment-toolbar"><el-input v-model="submissionSearch" placeholder="Tìm học viên" clearable class="search-input" /><el-select v-model="submissionStatusFilter" class="status-select"><el-option label="Tất cả trạng thái" value="ALL" /><el-option label="Chưa nộp" value="NOT_SUBMITTED" /><el-option label="Đã nộp" value="SUBMITTED" /><el-option label="Đã chấm" value="GRADED" /><el-option label="Cần nộp lại" value="REVISION_REQUIRED" /></el-select><el-button @click="reloadMatrix">Làm mới</el-button></div>
        <el-row :gutter="18">
          <el-col :xs="24" :lg="9"><el-card class="detail-card"><template #header><div class="card-header"><span>Thông tin bài tập</span><div class="card-actions"><el-button v-if="statusOf(assignment) === 'DRAFT'" link type="success" @click="publishNow(assignment)">Phát hành</el-button><el-button link type="primary" @click="openComments(assignment)">Thảo luận</el-button><el-button link type="primary" @click="openEdit(assignment)">Sửa</el-button><el-button link type="danger" @click="deleteAssign(assignment)">Xóa</el-button></div></div></template>
            <div class="title-line"><h3>{{ assignment.title }}</h3><span :class="['badge', statusOf(assignment) === 'PUBLISHED' ? 'badge-green' : 'badge-amber']">{{ statusOf(assignment) === 'PUBLISHED' ? 'Đã phát hành' : 'Bản nháp' }}</span></div>
            <p v-if="assignment.description" class="description">{{ assignment.description }}</p><p v-else class="subtle">Chưa có hướng dẫn chi tiết.</p>
            <p v-if="statusOf(assignment) === 'DRAFT' && publishAt(assignment)" class="schedule-note">Tự phát hành: {{ fmtDateTime(publishAt(assignment)) }}</p>
            <div class="detail-grid"><div><span>Hạn nộp</span><strong>{{ fmtDateTime(dueDate(assignment)) }}</strong></div><div><span>Thang điểm</span><strong>{{ maxScore(assignment) }} điểm</strong></div><div><span>Hình thức</span><strong>{{ submissionTypeLabel(assignment) }}</strong></div><div><span>Thời lượng</span><strong>{{ estimatedMinutes(assignment) ? `${estimatedMinutes(assignment)} phút` : 'Không ước tính' }}</strong></div></div>
            <div class="tag-row"><span :class="['badge', isRequired(assignment) ? 'badge-red' : 'badge-gray']">{{ isRequired(assignment) ? 'Bắt buộc' : 'Tự chọn' }}</span><span :class="['badge', allowLate(assignment) ? 'badge-green' : 'badge-orange']">{{ allowLate(assignment) ? 'Cho phép nộp trễ' : 'Không nhận nộp trễ' }}</span><span v-if="isGroup(assignment)" class="badge badge-purple">Bài tập nhóm</span></div>
            <div v-if="rubrics(assignment).length" class="rubric-summary"><p class="section-label">Rubric ({{ rubrics(assignment).length }} tiêu chí)</p><div v-for="rubric in rubrics(assignment)" :key="rubric.id" class="rubric-line"><span>{{ rubric.criterion }}</span><b>{{ rubric.maxPoints }}đ</b></div></div>
            <div v-if="attachments(assignment).length" class="attachment-section"><p class="section-label">Tài liệu đính kèm ({{ attachments(assignment).length }})</p><button v-for="file in attachments(assignment)" :key="file.id" class="attachment-link" @click="openFile(file.fileUrl)"><span class="file-name">{{ file.fileName }}</span><span>Mở</span></button></div>
            <div class="quick-actions"><el-button v-if="isGroup(assignment)" size="small" @click="openGroups(assignment)">Phân nhóm</el-button><el-button size="small" @click="openSimilarity(assignment)">Kiểm tra tương đồng</el-button></div>
            <el-divider /><div class="stat-grid"><div><span>Đã nộp</span><b class="green">{{ submittedCount }}</b></div><div><span>Chưa nộp</span><b class="red">{{ notSubmittedCount }}</b></div><div><span>Đã chấm</span><b class="blue">{{ gradedCount }}</b></div></div>
          </el-card></el-col>
          <el-col :xs="24" :lg="15" class="submission-column"><el-card><template #header><div class="card-header"><span>Tiến độ nộp bài</span><span class="subtle">{{ filteredMatrix.length }} học viên</span></div></template><el-table :data="filteredMatrix" :empty-text="'Chưa có học viên trong lớp'" class="submission-table"><el-table-column label="Học viên" prop="studentName" min-width="145"><template #default="{ row }"><div>{{ row.studentName }}</div><small v-if="row.groupName" class="table-muted">{{ row.groupName }}</small></template></el-table-column><el-table-column label="Trạng thái" width="130"><template #default="{ row }"><span :class="['badge', submissionBadge(row.status || 'NOT_SUBMITTED').cls]">{{ submissionBadge(row.status || 'NOT_SUBMITTED').label }}</span></template></el-table-column><el-table-column label="Nộp lúc" min-width="125"><template #default="{ row }"><span class="table-muted">{{ row.submittedAt ? fmtDateTime(row.submittedAt) : '—' }}</span></template></el-table-column><el-table-column label="Điểm" width="70"><template #default="{ row }">{{ row.score ?? '—' }}</template></el-table-column><el-table-column label="" width="135" fixed="right"><template #default="{ row }"><el-button v-if="row.submissionId" link type="primary" @click="viewSubmission(row)">Xem</el-button><el-button v-if="row.submissionId" link type="primary" @click="openGrade(row)">{{ row.status === 'GRADED' ? 'Sửa điểm' : 'Chấm' }}</el-button></template></el-table-column></el-table></el-card></el-col>
        </el-row>
