    <el-dialog v-model="showEditor" :title="editMode ? 'Cập nhật bài tập' : 'Tạo bài tập mới'" width="min(900px, 95vw)" destroy-on-close><el-form label-position="top" class="assignment-form"><el-row :gutter="16"><el-col :xs="24" :md="14"><el-form-item label="Tên bài tập *"><el-input v-model="formAssign.title" maxlength="255" show-word-limit placeholder="Ví dụ: Luyện viết chữ Hán bài 5" /></el-form-item></el-col><el-col :xs="24" :md="10"><el-form-item label="Hạn nộp *"><el-date-picker v-model="formAssign.dueDate" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="Chọn ngày, giờ" class="full-width" /></el-form-item></el-col></el-row><el-form-item label="Yêu cầu và hướng dẫn"><el-input v-model="formAssign.description" type="textarea" :rows="4" placeholder="Mô tả đầu bài, tiêu chí hoàn thành, cách nộp và lưu ý cho học viên." /></el-form-item><el-row :gutter="16"><el-col :xs="24" :sm="8"><el-form-item label="Thang điểm"><el-input-number v-model="formAssign.maxScore" :min="0.5" :max="100" :step="0.5" class="full-width" /></el-form-item></el-col><el-col :xs="24" :sm="8"><el-form-item label="Thời lượng dự kiến"><el-input-number v-model="formAssign.estimatedMinutes" :min="1" :max="1440" :step="5" class="full-width" /></el-form-item></el-col><el-col :xs="24" :sm="8"><el-form-item label="Hình thức nộp"><el-select v-model="formAssign.submissionType" class="full-width"><el-option label="Tệp và nội dung viết" value="BOTH" /><el-option label="Chỉ tệp đính kèm" value="FILE" /><el-option label="Chỉ nội dung viết" value="TEXT" /></el-select></el-form-item></el-col></el-row>
      <div class="switch-row"><el-switch v-model="formAssign.isRequired" active-text="Bài tập bắt buộc" /><el-switch v-model="formAssign.allowLateSubmission" active-text="Cho phép nộp trễ" /><el-switch v-model="formAssign.isGroupAssignment" active-text="Bài tập nhóm" /></div>
      <div v-if="formAssign.isGroupAssignment && !editMode" class="inline-group-editor">
