        <div v-if="!classStudents.length" class="rubric-empty">Lớp chưa có học viên để phân nhóm.</div>
        <div v-for="(group, index) in groupDrafts" :key="group.key" class="group-row">
          <el-input v-model="group.name" :placeholder="`Tên nhóm ${index + 1}`" class="group-name" />
          <el-select v-model="group.studentIds" multiple filterable collapse-tags :multiple-limit="Number(formAssign.groupMaxMembers) || 2" placeholder="Chọn học viên của nhóm" class="group-members">
