          </el-select>
          <el-button link type="danger" @click="groupDrafts.splice(index, 1)">Gỡ</el-button>
        </div>
        <div class="group-summary">Đã xếp {{ assignedStudentCount }}/{{ classStudents.length }} học viên</div>
      </div>
      <el-row :gutter="16"><el-col :xs="24" :md="12"><el-form-item label="Trạng thái"><el-radio-group v-model="formAssign.status"><el-radio value="PUBLISHED">Phát hành ngay</el-radio><el-radio value="DRAFT">Lưu nháp</el-radio></el-radio-group></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="Tự phát hành vào"><el-date-picker v-model="formAssign.publishAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="Để trống nếu không hẹn giờ" class="full-width" /></el-form-item></el-col></el-row>
      <div class="rubric-editor"><div class="section-head"><div><p class="section-label">Rubric chấm điểm</p><span class="subtle">Tổng {{ rubricTotal }} / {{ formAssign.maxScore }} điểm</span></div><el-button size="small" @click="addRubric">+ Thêm tiêu chí</el-button></div><div v-if="!formAssign.rubrics.length" class="rubric-empty">Chưa có rubric. Giáo viên vẫn có thể chấm điểm tổng.</div><div v-for="(rubric, index) in formAssign.rubrics" :key="rubric.key" class="rubric-edit-row"><el-input v-model="rubric.criterion" placeholder="Tiêu chí, ví dụ: Phát âm" /><el-input-number v-model="rubric.maxPoints" :min="0.5" :max="100" :step="0.5" controls-position="right" /><el-input v-model="rubric.description" placeholder="Mô tả mức đạt" /><el-button link type="danger" @click="removeRubric(index)">Gỡ</el-button></div></div>
      <el-form-item label="Tài liệu đính kèm"><el-upload v-model:file-list="pendingFiles" drag multiple :auto-upload="false" :limit="8" :accept="acceptedTypes" :on-change="validatePendingFile" :on-exceed="onAssignmentFileExceed"><div class="upload-copy"><b>Kéo thả hoặc chọn tối đa 8 tệp</b><span>PDF, Word, Excel, PowerPoint, ảnh, âm thanh, video, TXT/CSV/MD, ZIP/RAR/7Z. Mỗi tệp tối đa 100 MB.</span></div></el-upload></el-form-item><div v-if="editMode && existingAttachments.length" class="existing-files"><p class="section-label">Tệp đang có</p><div v-for="file in existingAttachments" :key="file.id" class="existing-file"><button @click="openFile(file.fileUrl)">{{ file.fileName }}</button><el-button link type="danger" @click="removeExistingAttachment(file)">Gỡ</el-button></div></div></el-form>
      <template #footer><el-button @click="saveAsTemplate">Lưu thành mẫu</el-button><el-button @click="closeEditor">Hủy</el-button><el-button type="primary" :loading="saving" @click="saveAssign">{{ editMode ? 'Lưu thay đổi' : 'Tạo bài tập' }}</el-button></template>
    </el-dialog>

    <el-dialog v-model="showGroups" :title="`Phân nhóm - ${groupAssignment?.title || ''}`" width="min(760px, 95vw)"><p class="subtle">Mỗi học viên chỉ thuộc một nhóm. Các thành viên cùng xem và nộp một bài chung.</p><div v-for="(group, index) in groupDrafts" :key="group.key" class="group-row"><el-input v-model="group.name" :placeholder="`Tên nhóm ${index + 1}`" class="group-name" /><el-select v-model="group.studentIds" multiple filterable placeholder="Chọn học viên" class="group-members"><el-option v-for="student in classStudents" :key="student.id" :label="student.fullName || student.full_name" :value="student.id" /></el-select><el-button link type="danger" @click="groupDrafts.splice(index, 1)">Gỡ</el-button></div><el-button plain @click="addGroup">+ Thêm nhóm</el-button><template #footer><el-button @click="showGroups = false">Hủy</el-button><el-button type="primary" :loading="savingGroups" @click="saveGroups">Lưu nhóm</el-button></template></el-dialog>

    <el-dialog v-model="showView" title="Bài làm của học viên" width="min(700px, 95vw)"><div v-if="viewRow" class="submission-view"><div class="view-meta"><b>{{ viewRow.studentName }}</b><span>{{ viewRow.groupName || '' }} {{ viewRow.submittedAt ? `· ${fmtDateTime(viewRow.submittedAt)}` : '' }}</span></div><span :class="['badge', submissionBadge(viewRow.status).cls]">{{ submissionBadge(viewRow.status).label }}</span><div v-if="viewRow.contentText" class="text-submission">{{ viewRow.contentText }}</div><div v-if="submissionAttachments(viewRow).length" class="submission-files"><p class="section-label">Tệp đã nộp</p><div v-for="file in submissionAttachments(viewRow)" :key="file.id" class="file-row"><span>{{ file.fileName }}</span><div><el-button link type="primary" @click="openFile(file.fileUrl)">Xem</el-button><el-button link @click="downloadFile(file.fileUrl, file.fileName)">Tải</el-button><el-button link type="warning" @click="openAnnotations(viewRow, file)">Nhận xét</el-button></div></div></div><div v-if="viewRow.rubricScores?.length" class="score-breakdown"><p class="section-label">Điểm theo rubric</p><div v-for="item in viewRow.rubricScores" :key="item.rubricId" class="rubric-line"><span>{{ item.criterion }}</span><b>{{ item.score }}/{{ item.maxPoints }}</b><small v-if="item.feedback">{{ item.feedback }}</small></div></div><div v-if="viewRow.score != null" class="result-box"><b>Điểm: {{ viewRow.score }}/{{ activeAssignment ? maxScore(activeAssignment) : 10 }}</b><p v-if="viewRow.teacherComment">{{ viewRow.teacherComment }}</p></div></div><template #footer><el-button @click="openHistory(viewRow)">Lịch sử phiên bản ({{ viewRow?.versionCount || 0 }})</el-button><el-button @click="showView = false">Đóng</el-button><el-button type="primary" @click="gradeFromView">Chấm bài</el-button></template></el-dialog>

    <el-dialog v-model="showGrade" title="Chấm bài" width="min(620px, 95vw)"><el-form v-if="gradeRow" label-position="top"><el-form-item label="Học viên"><b>{{ gradeRow.studentName }}</b><small v-if="gradeRow.groupName" class="subtle"> · {{ gradeRow.groupName }}</small></el-form-item><div v-if="rubrics(activeAssignment).length" class="grade-rubrics"><p class="section-label">Chấm theo rubric</p><div v-for="item in gradeForm.rubricScores" :key="item.rubricId" class="grade-rubric-row"><div><b>{{ item.criterion }}</b><small>{{ item.maxPoints }} điểm tối đa</small></div><el-input-number v-model="item.score" :min="0" :max="item.maxPoints" :step="0.5" /><el-input v-model="item.feedback" placeholder="Nhận xét tiêu chí" /></div><div class="rubric-total">Tổng điểm rubric: <b>{{ gradeRubricTotal }}/{{ gradeMax }}</b></div></div><el-form-item v-else :label="`Điểm (tối đa ${gradeMax})`"><el-input-number v-model="gradeForm.score" :min="0" :max="gradeMax" :precision="1" :step="0.5" /></el-form-item><el-form-item label="Nhận xét cho học viên"><el-input v-model="gradeForm.teacherComment" type="textarea" :rows="4" placeholder="Nêu điểm tốt, phần cần cải thiện và hướng dẫn chỉnh sửa." /></el-form-item><el-form-item label="Kết quả"><el-radio-group v-model="gradeForm.status"><el-radio value="GRADED">Hoàn thành</el-radio><el-radio value="REVISION_REQUIRED">Yêu cầu nộp lại</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button :loading="aiLoading" @click="suggestWithAi">AI gợi ý</el-button><el-button @click="showGrade = false">Hủy</el-button><el-button type="primary" :loading="grading" @click="saveGrade">Lưu đánh giá</el-button></template></el-dialog>

    <el-dialog v-model="showHistory" title="Lịch sử nộp bài" width="min(850px, 95vw)"><el-empty v-if="!versions.length" description="Chưa có phiên bản nộp lại" /><div v-for="version in versions" :key="version.id" class="version-card"><div><b>Phiên bản {{ version.versionNo }}</b><span>{{ fmtDateTime(version.createdAt) }}</span></div><p v-if="version.contentText">{{ version.contentText }}</p><div v-if="version.attachments?.length" class="version-files"><button v-for="file in version.attachments" :key="file.fileUrl" @click="openFile(file.fileUrl)">{{ file.fileName }}</button></div><small v-if="version.teacherComment">Điểm/nhận xét cũ: {{ version.score ?? '—' }} · {{ version.teacherComment }}</small></div><template #footer><el-button @click="showHistory = false">Đóng</el-button></template></el-dialog>

    <el-dialog v-model="showAnnotations" :title="`Nhận xét tệp - ${annotationFile?.fileName || ''}`" width="min(900px, 95vw)"><div v-if="annotationFile" class="annotation-layout"><div class="annotation-preview"><img v-if="isImage(annotationFile.fileUrl)" :src="mediaUrl(annotationFile.fileUrl)" @click="capturePosition" /><iframe v-else :src="mediaUrl(annotationFile.fileUrl)" title="Tệp bài nộp" /><span v-for="note in annotationsWithPosition" :key="note.id" class="annotation-pin" :style="{ left: `${note.positionX * 100}%`, top: `${note.positionY * 100}%` }" :title="note.content">●</span></div><div class="annotation-panel"><p class="section-label">Nhận xét đã lưu</p><div v-for="note in annotations" :key="note.id" class="annotation-note"><b>{{ note.authorName }}</b><span v-if="note.pageNo">Trang {{ note.pageNo }}</span><p>{{ note.content }}</p></div><el-empty v-if="!annotations.length" description="Chưa có nhận xét" /><el-divider /><el-input v-model="annotationForm.content" type="textarea" :rows="4" placeholder="Nhập nhận xét cho tệp hoặc vùng đang chọn" /><el-input-number v-model="annotationForm.pageNo" :min="1" placeholder="Trang PDF" class="page-number" /><small class="subtle">Với ảnh, bấm trực tiếp lên ảnh để ghim vị trí.</small></div></div><template #footer><el-button @click="showAnnotations = false">Đóng</el-button><el-button type="primary" :loading="savingAnnotation" @click="saveAnnotation">Lưu nhận xét</el-button></template></el-dialog>

    <el-dialog v-model="showSimilarity" title="Chỉ báo tương đồng nội dung" width="min(650px, 94vw)"><p class="subtle">Chỉ phân tích bài nộp dạng văn bản, dùng ngưỡng {{ similarityResult?.threshold || 35 }}%. Kết quả là tín hiệu để giáo viên kiểm tra, không phải kết luận đạo văn.</p><el-empty v-if="similarityResult && !similarityResult.matches.length" description="Không có cặp bài nộp vượt ngưỡng" /><el-table v-if="similarityResult?.matches.length" :data="similarityResult.matches"><el-table-column label="Bài nộp 1"><template #default="{ row }">{{ row.left.groupName || row.left.studentName }}</template></el-table-column><el-table-column label="Bài nộp 2"><template #default="{ row }">{{ row.right.groupName || row.right.studentName }}</template></el-table-column><el-table-column label="Tương đồng" width="120"><template #default="{ row }"><b>{{ row.similarity }}%</b></template></el-table-column></el-table><template #footer><el-button @click="showSimilarity = false">Đóng</el-button></template></el-dialog>

    <el-dialog v-model="showComments" :title="`Thảo luận: ${commentAssignment?.title || 'Bài tập'}`" width="min(720px, 94vw)">
      <div v-if="commentAssignment" class="discussion-context">
        <h3>{{ commentAssignment.title }}</h3>
        <p>{{ commentAssignment.description || 'Giáo viên chưa thêm yêu cầu chi tiết.' }}</p>
        <div class="discussion-meta"><span>Hạn nộp: <b>{{ fmtDateTime(dueDate(commentAssignment)) }}</b></span><span>Hình thức: <b>{{ submissionTypeLabel(commentAssignment) }}</b></span><span>Thang điểm: <b>{{ maxScore(commentAssignment) }}</b></span></div>
        <div v-if="attachments(commentAssignment).length" class="discussion-files"><b>Tài liệu bài tập</b><el-button v-for="file in attachments(commentAssignment)" :key="file.id" link type="primary" @click="openFile(file.fileUrl)">{{ file.fileName }}</el-button></div>
      </div>
      <div class="discussion-heading">Trao đổi của lớp</div>
      <div class="comments-box"><div v-for="comment in comments" :key="comment.id" class="comment-row"><b>{{ comment.authorName || 'Người dùng' }}</b><span>{{ fmtDateTime(comment.createdAt) }}</span><p>{{ comment.content }}</p></div><el-empty v-if="!comments.length" description="Chưa có bình luận. Hãy bắt đầu cuộc thảo luận." /></div>
      <el-input v-model="commentText" type="textarea" :rows="3" placeholder="Nhập câu hỏi hoặc phản hồi về bài tập..." />
      <template #footer><el-button @click="showComments = false">Đóng</el-button><el-button type="primary" @click="addComment">Gửi</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
